# Figure 4 | Varga (2025) §4.1 | Two-factor Poisson Lee-Carter
# ACTUAL GBD fitting: select the fitted_rates.csv generated by the
# preceding one-factor fit; it contains ORIGINAL deaths_gbd and exposure_proxy.
# It does NOT use its one-factor fitted values to estimate the two-factor model.
# 1980-2015, 6 ages x 36 years x 9 causes x 2 sexes.
#
# Run in RStudio:
#   source(file.choose())  # select THIS R file
#   -> select your saved fitted_rates.csv in the next dialog
#   -> inspect figures / diagnostics; type y to save
#
# Optional command line: Rscript run_4_1_poisson_lc_2factor.R input.csv output_dir
# Base R only. GBD modeled noninteger deaths => Poisson mean-based
# pseudo-likelihood, NOT a literal integer-count sampling assertion.
#
# IDENTIFICATION: fit with 2x2 anchor-beta block fixed to I, center kappa
# columns, then SVD-canonicalize the two-factor surface: orthonormal
# beta columns, descending singular values, centered kappa, deterministic
# signs (largest magnitude beta entry positive). This differs from the
# paper's sum(beta)=1 convention but is immune to near-zero beta-sum.
# The algorithm checks identical log-mortality before/after normalization.

suppressWarnings(options(stringsAsFactors = FALSE))
argv <- commandArgs(trailingOnly = TRUE)
if (!interactive() && length(argv) < 2L)
  stop("Rscript usage: Rscript run_4_1_poisson_lc_2factor.R fitted_rates.csv output_dir")
if (interactive()) {
  cat("请选择此前 Figure 3 运行生成的 fitted_rates.csv：\n")
  inpath <- file.choose()
} else {
  inpath <- argv[1]
}
raw <- read.csv(inpath, stringsAsFactors = FALSE, check.names = FALSE)
required <- c("sex_name","cause_name","age_name","year","deaths_gbd",
              "exposure_proxy","fitted_count")
if (!all(required %in% names(raw)))
  stop("fitted_rates.csv 缺少列：", paste(setdiff(required,names(raw)),collapse=", "))
ages <- c("60-64 years","65-69 years","70-74 years",
          "75-79 years","80-84 years","85-89 years")
age_mid <- c(62,67,72,77,82,87)
years <- 1980:2015
sexes <- c("Male","Female")
causes <- unique(raw$cause_name)
A <- length(ages); Tn <- length(years); R <- 2L
if (length(causes) != 9L || nrow(raw) != 9L*2L*A*Tn ||
    !setequal(raw$year, years) || !setequal(raw$age_name,ages) ||
    !setequal(raw$sex_name,sexes) ||
    anyDuplicated(raw[c("sex_name","cause_name","year","age_name")]) ||
    anyNA(raw[required]) ||
    any(!is.finite(raw$deaths_gbd) | raw$deaths_gbd < 0) ||
    any(!is.finite(raw$exposure_proxy) | raw$exposure_proxy <= 0) ||
    any(!is.finite(raw$fitted_count) | raw$fitted_count <= 0))
  stop("原 Figure 3 输出数据范围、单元、缺失值或数值未通过检查。")
# order groups by the original fitted_rates.csv appearance
causes <- causes[!duplicated(causes)]
cat("GBD actual observations: ",nrow(raw)," rows; causes=",length(causes),
    "; sexes=2; age groups=6; training years=",length(years),"\n",sep="")
cat("NOTE: no 2016-2019 holdout used in fitting.\n")

poisson_dev <- function(D, mu) {
  if (any(!is.finite(mu)) || any(mu <= 0)) return(Inf)
  nz <- D > 0
  2*(sum(mu-D)+sum(D[nz]*log(D[nz]/mu[nz])))
}

fit_two_factor <- function(D,E,seed=20261110L) {
  stopifnot(identical(dim(D),c(A,Tn)),identical(dim(E),c(A,Tn)),
            all(D>=0),all(E>0),all(is.finite(D)),all(is.finite(E)))
  logE <- log(E)
  z <- log((D+0.5)/E)
  a0 <- rowMeans(z)
  zc <- sweep(z,1L,a0,"-")
  sv <- svd(zc,nu=2L,nv=2L)
  if (sv$d[2] <= 1e-8) stop("数据第二奇异值过小，二因子无法初始化")
  # Two anchor ages maximize the absolute determinant of the 2D SVD loadings.
  pair <- combn(A,2L)
  dets <- apply(pair,2L,function(v) abs(det(sv$u[v,1:2,drop=FALSE])))
  anchor <- pair[,which.max(dets)]
  M <- sv$u[anchor,1:2,drop=FALSE]
  if (abs(det(M)) < 1e-8) stop("2x2 beta anchor ill-conditioned")
  B0 <- sv$u[,1:2,drop=FALSE] %*% solve(M)
  K0 <- sv$v[,1:2,drop=FALSE] %*% diag(sv$d[1:2],2) %*% t(M)
  a0 <- a0 + as.vector(B0 %*% colMeans(K0))
  K0 <- sweep(K0,2L,colMeans(K0),"-")
  # Using beta[anchor,] = I fixes the 2x2 mixing indeterminacy.
  free <- setdiff(seq_len(A),anchor)
  nB <- length(free)*R
  nK <- (Tn-1L)*R
  pack <- function(alpha,B,K)
    c(alpha,as.vector(B[free,,drop=FALSE]),
      as.vector(K[seq_len(Tn-1L),,drop=FALSE]))
  unpack <- function(theta) {
    alpha <- theta[seq_len(A)]
    B <- matrix(0,A,R); B[anchor,] <- diag(R)
    B[free,] <- matrix(theta[A+seq_len(nB)],nrow=length(free))
    K <- matrix(0,Tn,R)
    K[seq_len(Tn-1L),] <- matrix(theta[A+nB+seq_len(nK)],nrow=Tn-1L)
    K[Tn,] <- -colSums(K[seq_len(Tn-1L),,drop=FALSE])
    list(alpha=alpha,B=B,K=K)
  }
  total <- sum(D)
  if (total<=0)stop("No deaths")
  calc <- function(theta) {
    q <- unpack(theta)
    eta <- sweep(q$B %*% t(q$K),1L,q$alpha,"+")
    logmu <- logE + eta
    if (any(!is.finite(logmu)) || max(logmu)>50) return(NULL)
    mu <- exp(logmu)
    if(any(!is.finite(mu)))return(NULL)
    res <- mu-D
    nz <- D>0
    dv <- 2*(sum(res)+sum(D[nz]*(log(D[nz])-logmu[nz])))
    ga <- rowSums(res)
    gb <- res %*% q$K
    gk <- t(res) %*% q$B
    gkfree <- sweep(gk[seq_len(Tn-1L),,drop=FALSE],2L,gk[Tn,],"-")
    grad <- c(ga,as.vector(gb[free,,drop=FALSE]),
              as.vector(gkfree))/total
    list(value=dv/(2*total),dev=dv,grad=grad,
         eta=eta,mu=mu,alpha=q$alpha,B=q$B,K=q$K)
  }
  fn <- function(th) {v<-calc(th);if(is.null(v))1e50 else v$value}
  gr <- function(th) {v<-calc(th);if(is.null(v))rep(0,length(th)) else v$grad}
  init <- pack(a0,B0,K0)
  set.seed(seed)
  initlist <- list(init)
  for (j in 1:2) {
    Bnew <- B0; Knew <- K0
    Bnew[free,] <- Bnew[free,]+matrix(rnorm(nB,sd=0.035),nrow=length(free))
    Knew[1:(Tn-1L),] <- Knew[1:(Tn-1L),]+
      matrix(rnorm(nK,sd=max(sd(as.vector(K0)),0.05)*0.02),nrow=Tn-1L)
    Knew[Tn,] <- -colSums(Knew[1:(Tn-1L),,drop=FALSE])
    initlist[[j+1L]] <- pack(a0,Bnew,Knew)
  }
  fits <- lapply(initlist,function(start) {
    f <- tryCatch(optim(start,fn,gr,method="BFGS",
                 control=list(maxit=7000L,reltol=1e-11)),error=function(e)NULL)
    if(is.null(f))return(NULL)
    q <- calc(f$par)
    if(is.null(q))return(NULL)
    list(q=q,convergence=f$convergence,objective=q$value,
         gradient=max(abs(q$grad)))
  })
  good <- Filter(function(x)!is.null(x)&&is.finite(x$objective)&&
                 x$convergence==0L&&x$gradient<0.03,fits)
  if(!length(good)) {
    print(lapply(fits,function(x)if(is.null(x))"ERROR" else
                       c(code=x$convergence,max_gradient=x$gradient,
                         objective=x$objective)))
    stop("二因子 Poisson LC 未满足优化收敛要求。不能用未收敛参数作正式结果。")
  }
  best <- good[[which.min(vapply(good,function(x)x$objective,numeric(1)))]]
  q <- best$q
  # Canonical, rotation-invariant representation of fitted rank-2 surface.
  F <- q$B %*% t(q$K)
  S <- svd(F,nu=2L,nv=2L)
  beta <- S$u[,1:2,drop=FALSE]
  kappa <- S$v[,1:2,drop=FALSE] %*% diag(S$d[1:2],2)
  for (j in 1:2) {
    imax <- which.max(abs(beta[,j]))
    if(beta[imax,j]<0) {beta[,j]<- -beta[,j]; kappa[,j]<- -kappa[,j]}
  }
  eta_new <- sweep(beta %*% t(kappa),1L,q$alpha,"+")
  err <- max(abs(eta_new-q$eta))
  if(err>1e-7)stop("SVD 识别后拟合对数死亡率变化：",err)
  if(max(abs(colMeans(kappa)))>1e-7)stop("时间因子未中心化")
  ratio <- abs(colSums(beta))/colSums(abs(beta))
  flag <- if (any(ratio < 0.08)) "REVIEW_near_zero_beta_sum" else "OK"
  singular_ratio <- S$d[2]/S$d[1]
  if(singular_ratio>0.85)flag <- paste0(flag,";REVIEW_factor_order")
  if(singular_ratio<0.02)flag <- paste0(flag,";REVIEW_weak_factor2")
  list(alpha=q$alpha,beta=beta,kappa=kappa,
       mu=q$mu,eta=eta_new,dev=q$dev,objective=best$objective,
       n_converged=length(good),max_gradient=best$gradient,
       convergence=best$convergence,canonical_error=err,
       singular_1=S$d[1],singular_2=S$d[2],
       singular_ratio_2_to_1=singular_ratio,
       beta_cancellation_1=ratio[1],beta_cancellation_2=ratio[2],
       factor_flag=flag,anchor_ages=paste(age_mid[anchor],collapse="/"))
}

allfits <- list()
stats <- alpha_tab <- beta_tab <- kappa_tab <- fitted_tab <- data.frame()
for (sx in sexes) for (cause in causes) {
  dat <- raw[raw$sex_name==sx&raw$cause_name==cause,]
  dat <- dat[order(match(dat$age_name,ages),match(dat$year,years)),]
  if(nrow(dat)!=A*Tn ||
     !identical(dat$age_name,rep(ages,each=Tn)) ||
     !identical(dat$year,rep(years,times=A)))
    stop("年龄 x 年份网格不完整：",sx," ",cause)
  D <- matrix(dat$deaths_gbd,nrow=A,byrow=TRUE)
  E <- matrix(dat$exposure_proxy,nrow=A,byrow=TRUE)
  baseline <- matrix(dat$fitted_count,nrow=A,byrow=TRUE)
  cat("重新拟合二因子：",sx," | ",cause,"\n")
  f <- fit_two_factor(D,E,seed=20261110L+
                         match(sx,sexes)*100L+match(cause,causes))
  dev1 <- poisson_dev(D,baseline)
  dev2 <- f$dev
  if(dev2>dev1+max(1e-5,dev1*1e-7)) {
    warning("二因子拟合偏差高于已有一因子：",sx," ",cause,
            "，可能为局部极值。需复核，不作为改进证据。")
  }
  p1 <- A+(A-1L)+(Tn-1L)            # 46
  p2 <- A+R*(A+Tn-1L-R)           # 84
  n <- A*Tn
  allfits[[paste(sx,cause,sep="__")]]<-f
  stats <- rbind(stats,data.frame(sex_name=sx,cause_name=cause,
    deviance_1factor=dev1,deviance_2factor=dev2,
    deviance_reduction=dev1-dev2,
    pseudo_AIC_delta_2_minus_1=(dev2+2*p2)-(dev1+2*p1),
    pseudo_BIC_delta_2_minus_1=(dev2+p2*log(n))-(dev1+p1*log(n)),
    convergence_code=f$convergence,max_abs_gradient=f$max_gradient,
    successful_starts=f$n_converged,
    singular_ratio_2_to_1=f$singular_ratio_2_to_1,
    beta_cancellation_1=f$beta_cancellation_1,
    beta_cancellation_2=f$beta_cancellation_2,
    canonical_reconstruction_error=f$canonical_error,
    identification=f$anchor_ages,factor_flag=f$factor_flag))
  alpha_tab<-rbind(alpha_tab,data.frame(sex_name=sx,cause_name=cause,
                          age_name=ages,age_midpoint=age_mid,alpha=f$alpha))
  beta_tab<-rbind(beta_tab,data.frame(sex_name=sx,cause_name=cause,
                          age_name=rep(ages,2),age_midpoint=rep(age_mid,2),
                          factor=rep(1:2,each=A),beta=c(f$beta)))
  kappa_tab<-rbind(kappa_tab,data.frame(sex_name=sx,cause_name=cause,
                        year=rep(years,2),factor=rep(1:2,each=Tn),
                        kappa=c(f$kappa)))
  fitted_tab<-rbind(fitted_tab,data.frame(sex_name=sx,cause_name=cause,
        age_name=rep(ages,each=Tn),year=rep(years,times=A),
        deaths_gbd=as.vector(t(D)),exposure_proxy=as.vector(t(E)),
        onefactor_fitted_count=as.vector(t(baseline)),
        twofactor_fitted_count=as.vector(t(f$mu)),
        twofactor_pearson_residual=as.vector(t((D-f$mu)/sqrt(f$mu)))))
}
cat("\n--- REAL DATA model comparison (in-sample) ---\n")
print(stats[,c("sex_name","cause_name","deviance_1factor",
              "deviance_2factor","deviance_reduction",
              "pseudo_AIC_delta_2_minus_1",
              "pseudo_BIC_delta_2_minus_1","factor_flag")],row.names=FALSE)
if(any(stats$deviance_reduction < -1e-4))
  warning("至少一组二因子不如单因子；请检查数值优化。")
cat("\nImportant: these are in-sample pseudo-likelihood diagnostics, NOT test forecasts.\n")

pal <- grDevices::hcl.colors(length(causes),"Dark 3")
names(pal) <- causes
plot_sex <- function(sx) {
  op <- par(no.readonly=TRUE)
  on.exit({layout(1);par(op)})
  layout(matrix(c(1,2,3,4,5,6,7,7,7),nrow=3,byrow=TRUE),
         heights=c(1,1,0.35))
  par(mar=c(3.7,4.2,3.3,1.1),oma=c(0.2,0.2,2.6,0.2))
  for (variable in c("alpha","beta_1","beta_2","kappa_1","kappa_2")) {
    curves <- lapply(causes,function(cause) {
      f <- allfits[[paste(sx,cause,sep="__")]]
      switch(variable,alpha=f$alpha,beta_1=f$beta[,1],
             beta_2=f$beta[,2],kappa_1=f$kappa[,1],kappa_2=f$kappa[,2])
    })
    x <- if(startsWith(variable,"kappa")) years else age_mid
    vals <- unlist(curves)
    ylim <- range(vals,finite=TRUE)
    if(diff(ylim)==0) ylim<-ylim+c(-1,1)*1e-5
    plot(x,curves[[1]],type="n",ylim=ylim,main=variable,
         xlab=if(startsWith(variable,"kappa"))"Year" else "Age midpoint",
         ylab=variable)
    for(i in seq_along(causes))
      lines(x,curves[[i]],col=pal[causes[i]],lwd=1.6)
  }
  plot.new()
  text(.04,.86,"SVD canonical identification",adj=c(0,1),cex=.9,font=2)
  text(.04,.65,"beta columns orthogonal; kappa centered",adj=c(0,1),cex=.77)
  text(.04,.48,"Factor 1 = larger singular component",adj=c(0,1),cex=.77)
  text(.04,.3,"Factor 2 = smaller singular component",adj=c(0,1),cex=.77)
  text(.04,.12,"GBD data; not original HCSO estimates",adj=c(0,1),cex=.7)
  par(mar=c(0,0,0,0));plot.new()
  legend("center",legend=causes,col=pal,lty=1,lwd=2,ncol=3,bty="n",cex=.68)
  mtext(paste("Figure 4 style | 2-factor Poisson LC |",sx,
              "| GBD 1980-2015"),outer=TRUE,side=3,line=.7,cex=1.05,font=2)
}
plot_comparison <- function(){
  op<-par(no.readonly=TRUE);on.exit(par(op))
  par(mar=c(7,4.8,3.8,1))
  s<-stats[order(stats$sex_name,stats$cause_name),]
  xs<-seq_len(nrow(s));y<-s$deviance_reduction
  cols<-ifelse(s$sex_name=="Male","#3778a6","#c47649")
  plot(xs,y,type="h",lwd=6,col=cols,xaxt="n",
       xlab="",ylab="Deviance(1 factor) - Deviance(2 factors)",
       main="Training fit improvement: 1-factor vs 2-factor",ylim=range(c(0,y)))
  abline(h=0,lty=2,col="grey50")
  axis(1,at=xs,labels=paste(substr(s$sex_name,1,1),
                           substr(s$cause_name,1,14),sep=" | "),
       las=2,cex.axis=.64)
  legend("topright",legend=c("Male","Female"),
         col=c("#3778a6","#c47649"),lty=1,lwd=4,bty="n")
}
# -----------------------------------------------------------------------
# FIXED on 2026-11-10 after user RStudio screenshot:
# 1. The previous script displayed the deviance bar plot LAST, so users
#    thought the bar chart was Figure 4.
# 2. RStudio Source/readline may return "" without a prompt, leaving outdir
#    undefined and causing 'object outdir not found' when lines are run.
# The figures and all CSVs are now saved AUTOMATICALLY. No readline.
# The actual paper-style MALE Figure 4 is displayed LAST in Plots.
# RStudio Plots back-arrow shows Female and the comparison.
# -----------------------------------------------------------------------
outdir <- if(interactive()) {
  file.path(dirname(normalizePath(inpath, winslash="/",mustWork=TRUE)),
            paste0("Figure4_Poisson_LC_2factor_",
                   format(Sys.time(),"%Y%m%d_%H%M%S")))
} else argv[2]
if (!dir.exists(outdir) && !dir.create(outdir,recursive=TRUE,
                                       showWarnings=FALSE))
  stop("无法创建 Figure 4 输出目录：",outdir)

write.csv(stats,file.path(outdir,"fit_diagnostics_2factor.csv"),row.names=FALSE)
write.csv(alpha_tab,file.path(outdir,"alpha_2factor.csv"),row.names=FALSE)
write.csv(beta_tab,file.path(outdir,"beta_2factor.csv"),row.names=FALSE)
write.csv(kappa_tab,file.path(outdir,"kappa_2factor.csv"),row.names=FALSE)
write.csv(fitted_tab,file.path(outdir,"fitted_rates_2factor.csv"),row.names=FALSE)
k2 <- subset(kappa_tab,factor==2L,select=c(sex_name,cause_name,year,kappa))
k2$model<-"Poisson LC 2factor";k2$factor<-2L
write.csv(k2,file.path(outdir,"kappa_factor2_for_DTW.csv"),row.names=FALSE)
for(sx in sexes) {
  grDevices::png(file.path(outdir,paste0("figure4_",tolower(sx),".png")),
                 width=2200,height=1600,res=150)
  plot_sex(sx);grDevices::dev.off()
}
grDevices::png(file.path(outdir,"figure4_deviance_comparison.png"),
               width=2200,height=1100,res=160)
plot_comparison();grDevices::dev.off()
writeLines(c("GBD Figure 4 two-factor Poisson LC",
   paste("Source:",normalizePath(inpath,winslash="/")),
   "Data: ORIGINAL deaths_gbd and exposure_proxy. fitted_count only comparison.",
   "Years: 1980-2015; ages: 60-89 in six groups; 9 causes x 2 sexes.",
   "Poisson mean pseudo-likelihood of GBD modeled estimated deaths.",
   "Canonicalization: centered SVD with orthonormal beta and ordered factors.",
   "2x2 anchor ages + BFGS 3 starts per group.",
   "Do not interpret training improvements as out-of-sample forecast gains.",
   "The displayed main chart is a PARAMETER figure, not bar chart.",
   paste("Run date:",Sys.time())),
   file.path(outdir,"METHOD_AND_LIMITATIONS.txt"))

cat("\nSUCCESS — all Figure 4 figures and tables saved to:\n",
    normalizePath(outdir,winslash="/",mustWork=TRUE),"\n")
print(list.files(outdir))
cat("\nPlots will now display: model-comparison bar plot; female Figure 4; MALE Figure 4 LAST.\n")
cat("Use RStudio Plots LEFT arrow for the earlier charts.\n")
# Make the main plot the very last figure on the RStudio device.
if(interactive()) {
  plot_comparison()
  plot_sex("Female")
  plot_sex("Male")
  View(stats,title="Two-factor Poisson LC diagnostics")
}
